ALTER TABLE public.profiles ADD COLUMN primary_position text, ADD COLUMN secondary_position text;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_primary_position_valid CHECK (primary_position IS NULL OR primary_position IN ('Goleiro', 'Pivô', 'Ala', 'Fixo')), ADD CONSTRAINT profiles_secondary_position_valid CHECK (secondary_position IS NULL OR secondary_position IN ('Goleiro', 'Pivô', 'Ala', 'Fixo')), ADD CONSTRAINT profiles_distinct_positions CHECK (primary_position IS NULL OR secondary_position IS NULL OR primary_position <> secondary_position);
CREATE OR REPLACE FUNCTION public.get_player_profile(p_user uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$
 SELECT jsonb_build_object('id',p.id,'name',p.name,'avatar_url',p.avatar_url,'rating',p.rating,'wins',p.wins,'losses',p.losses,'primary_position',p.primary_position,'secondary_position',p.secondary_position,'stats',(SELECT jsonb_build_object('games',count(*),'goals',coalesce(sum(s.goals),0),'assists',coalesce(sum(s.assists),0),'passes',coalesce(sum(s.passes),0),'interceptions',coalesce(sum(s.interceptions),0),'saves',coalesce(sum(s.saves),0),'gk_saves',coalesce(sum(s.saves) FILTER (WHERE mp.position='Goleiro'),0),'gk_games',count(*) FILTER (WHERE mp.position='Goleiro'),'mvps',count(*) FILTER (WHERE s.mvp),'score',coalesce(sum(s.score),0)) FROM public.match_player_stats s JOIN public.matches m ON m.id=s.match_id AND m.status <> 'cancelled' LEFT JOIN public.match_players mp ON mp.match_id=s.match_id AND mp.user_id=s.user_id WHERE s.user_id=p.id)) FROM public.profiles p WHERE p.id=p_user AND NOT p.is_ghost;
$$;
REVOKE ALL ON FUNCTION public.get_player_profile(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_player_profile(uuid) TO anon, authenticated, service_role;